+'use client';
+
+import { useState, useEffect, useRef, useCallback } from 'react';
+import { LocationResult } from '@/lib/maptiler';
+import { convertToUTC } from '@/lib/timezone';
+
+interface CosmicBirthFormProps {
+  onSubmit: (data: { datetime_utc: string; lat: number; lng: number }) => void;
+  isLoading: boolean;
+  error: string | null;
+}
+
+interface Location {
+  lat: number;
+  lng: number;
+  displayName: string;
+  timezone: string;
+}
+
+export function CosmicBirthForm({ onSubmit, isLoading, error }: CosmicBirthFormProps) {
+  const [birthDate, setBirthDate] = useState('');
+  const [birthTime, setBirthTime] = useState('');
+  const [location, setLocation] = useState<Location | null>(null);
+  const [validationError, setValidationError] = useState<string | null>(null);
+
+  // Location search state
+  const [query, setQuery] = useState('');
+  const [results, setResults] = useState<LocationResult[]>([]);
+  const [isSearching, setIsSearching] = useState(false);
+  const [isOpen, setIsOpen] = useState(false);
+  const [selectedIndex, setSelectedIndex] = useState(-1);
+  const [hasSelected, setHasSelected] = useState(false);
+  const containerRef = useRef<HTMLDivElement>(null);
+
+  const timezone = location?.timezone || 'UTC';
+
+  const handleSubmit = (e: React.FormEvent) => {
+    e.preventDefault();
+    setValidationError(null);
+
+    if (!birthDate || !birthTime || !location) {
+      setValidationError('Please fill in all required fields');
+      return;
+    }
+
+    // Convert local time in birth location timezone to UTC
+    const localDateTimeString = `${birthDate}T${birthTime}:00`;
+    const utcString = convertToUTC(localDateTimeString, location.timezone);
+
+    onSubmit({
+      datetime_utc: utcString,
+      lat: location.lat,
+      lng: location.lng,
+    });
+  };
+
+  // Location search effect
+  useEffect(() => {
+    if (hasSelected) return;
+    if (query.length < 2) {
+      setResults([]);
+      setIsOpen(false);
+      return;
+    }
+
+    const timeoutId = setTimeout(async () => {
+      setIsSearching(true);
+      try {
+        const response = await fetch(`/api/geocode?q=${encodeURIComponent(query)}`);
+        if (response.ok) {
+          const data: LocationResult[] = await response.json();
+          setResults(data);
+          setIsOpen(data.length > 0);
+          setSelectedIndex(-1);
+        }
+      } catch {
+        setResults([]);
+        setIsOpen(false);
+      } finally {
+        setIsSearching(false);
+      }
+    }, 300);
+
+    return () => clearTimeout(timeoutId);
+  }, [query, hasSelected]);
+
+  // Click outside to close
+  useEffect(() => {
+    function handleClickOutside(event: MouseEvent) {
+      if (containerRef.current && !containerRef.current.contains(event.target as Node)) {
+        setIsOpen(false);
+      }
+    }
+    document.addEventListener('mousedown', handleClickOutside);
+    return () => document.removeEventListener('mousedown', handleClickOutside);
+  }, []);
+
+  const handleSelectLocation = useCallback((loc: LocationResult) => {
+    setQuery(loc.displayName);
+    setHasSelected(true);
+    setIsOpen(false);
+    setResults([]);
+    setLocation({
+      lat: loc.lat,
+      lng: loc.lng,
+      displayName: loc.displayName,
+      timezone: loc.timezone || 'UTC',
+    });
+  }, []);
+
+  const handleKeyDown = (e: React.KeyboardEvent) => {
+    if (!isOpen) return;
+    switch (e.key) {
+      case 'ArrowDown':
+        e.preventDefault();
+        setSelectedIndex((prev) => (prev < results.length - 1 ? prev + 1 : prev));
+        break;
+      case 'ArrowUp':
+        e.preventDefault();
+        setSelectedIndex((prev) => (prev > 0 ? prev - 1 : -1));
+        break;
+      case 'Enter':
+        e.preventDefault();
+        if (selectedIndex >= 0 && results[selectedIndex]) {
+          handleSelectLocation(results[selectedIndex]);
+        }
+        break;
+      case 'Escape':
+        setIsOpen(false);
+        setSelectedIndex(-1);
+        break;
+    }
+  };
+
+  const displayError = validationError || error;
+
+  return (
+    <form onSubmit={handleSubmit}>
+      {displayError && (
+        <div className="mb-6 p-4 bg-red-50 border border-red-200 rounded-2xl text-red-600 text-sm font-mono">
+          {displayError}
+        </div>
+      )}
+      <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-4">
